import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"Pin","description":"","frontmatter":{},"headers":[],"relativePath":"components/pin.md","filePath":"components/pin.md"}'),i={name:"components/pin.md"};function r(n,e,c,s,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="pin" tabindex="-1">Pin <a class="header-anchor" href="#pin" aria-label="Permalink to &quot;Pin&quot;">​</a></h1><p>Pin is a mark that stands on a point of the stage: the people of a comment, or a point being placed.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it to mark a point of the stage; the people who are here now, in a toolbar, are a <a href="./presence">Presence</a>. Place it absolutely at the point, which is its top left corner; the pin hangs down and to the right and never moves. By default it holds small <a href="./avatar">Avatars</a> and <code>more</code> for the rest; <code>solid</code> is a point being placed, with one icon. With <code>onclick</code> it is a button and needs a <code>label</code>; <code>active</code> shows that what it opens is open.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>label</code></td><td></td><td>The accessible name; required with <code>onclick</code></td></tr><tr><td><code>onclick</code></td><td></td><td>Makes the pin a button</td></tr><tr><td><code>solid</code></td><td><code>false</code></td><td>A point being placed: filled, with one icon</td></tr><tr><td><code>active</code></td><td><code>false</code></td><td>Selected: filled</td></tr><tr><td><code>more</code></td><td></td><td>The count of the others, such as <code>+2</code></td></tr><tr><td><code>children</code></td><td>required</td><td>Small avatars, or an icon</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A capsule with a square top left corner, the panel surface and a strong line, no shadow; pad-2xs inside. Small avatars overlap by gap-xs; <code>more</code> is text on the raise-2 surface, as tall as a badge. <code>active</code> fills it with the solid color; <code>solid</code> is a filled square of an icon button with its icon centred. As a button it has <code>aria-pressed</code>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/pin/" title="Pin" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/pin/" target="_blank" rel="noopener">Pin</a></figcaption></figure>',10)])])}const m=t(i,[["render",r]]);export{f as __pageData,m as default};
